"""Finite Galois selector character decomposition, without normality claims."""
from __future__ import annotations
from fractions import Fraction
from math import gcd, cos, sin, pi
import json
from prime_certificate import source

def phase(q):
    q=Fraction(q)%1
    t=2*pi*float(q)
    return complex(cos(t),sin(t))

def units15_with_characters():
    # (Z/15)^* = C_2 x C_4, generated by 11 and 2.
    exponents={}
    for i in range(2):
        for j in range(4):
            u=pow(11,i,15)*pow(2,j,15)%15
            assert u not in exponents
            exponents[u]=(i,j)
    assert set(exponents)=={1,2,4,7,8,11,13,14}
    table=[]
    for s in range(2):
        for t in range(4):
            table.append({u:phase(Fraction(s*i,2)+Fraction(t*j,4))
                          for u,(i,j) in exponents.items()})
    return table

def primitive_root(p):
    assert p>2
    for g in range(2,p):
        if len({pow(g,j,p) for j in range(p-1)})==p-1:
            return g
    raise AssertionError(p)

def prime_characters(p):
    g=primitive_root(p)
    exponents={pow(g,j,p):j for j in range(p-1)}
    assert len(exponents)==p-1
    return [{u:phase(Fraction(k*j,p-1)) for u,j in exponents.items()}
            for k in range(p-1)]

def table_test(d,a,h,table):
    unit_set={u for u in range(1,d) if gcd(u,d)==1}
    assert all(set(row)==unit_set for row in table)
    assert len(table)==len(unit_set)
    truth={u:phase(Fraction(h*a*u,d)) for u in unit_set}
    amp=[sum(truth[u]*row[u].conjugate() for u in unit_set)/len(unit_set)
         for row in table]
    assert all(abs(sum(amp[k]*row[u] for k,row in enumerate(table))-truth[u])<5e-12
               for u in unit_set)
    assert abs(sum(abs(x)**2 for x in amp)-1)<5e-12
    mean=sum(truth.values())/len(unit_set)
    assert abs(amp[0]-mean)<5e-12
    return {'d':d,'a_mod_d':a%d,'h':h,'character_count':len(table),
            'trivial_mean_abs_float':round(abs(amp[0]),12),
            'nontrivial_L2_energy_float':round(sum(abs(v)**2 for v in amp[1:]),12),
            'selected_phase_abs_float':round(abs(truth[1]),12),
            'nontrivial_coherent_sum_abs_float':round(abs(sum(amp[1:])),12)}

def ramanujan_by_units(d,h):
    from cmath import exp
    return sum(phase(Fraction(h*u,d)) for u in range(1,d) if gcd(u,d)==1)

def run():
    original=[];U=Fraction(0)
    for n in range(1,9):
        U=16*U+source(n)
        assert U.denominator%2==1
        assert gcd(U.numerator,U.denominator)==1
        original.append({'n':n,'denominator_bits':U.denominator.bit_length(),
                         'numerator_coprime':True})
        if n==1:assert U==Fraction(47,15)
    tables=[]
    for h in (1,2,3,4,5):
        entry=table_test(15,47,h,units15_with_characters())
        assert abs(entry['trivial_mean_abs_float']-abs(ramanujan_by_units(15,h)/8))<1e-10
        tables.append(entry)
    for p in (7,11,17):
        for h in (1,2,3):
            entry=table_test(p,2,h,prime_characters(p))
            assert abs(entry['trivial_mean_abs_float']-1/(p-1))<1e-10
            tables.append(entry)
    mutant=table_test(15,3,1,units15_with_characters())
    assert abs(mutant['trivial_mean_abs_float']-0.25)<1e-11
    return {'label':'OBSERVED FINITE Fourier-table calibration; exact proof in GALOIS_SELECTOR_THEOREM.md',
            'original_U0':'0','original_prefix':original,
            'G15_and_prime_character_tables':tables,
            'noncoprime_mutant_trivial_mean':mutant,
            'all_n_source_trivial_sector_exponentially_small':'PROVED LOCAL from PF6 + Ramanujan',
            'selected_real_time_character_cancellation':'OPEN',
            'pi_base16_normality':'OPEN'}

if __name__=='__main__':print(json.dumps(run(),indent=2,sort_keys=True))
